  ('95bf40df-3622-5b06-979a-b59376d804fa', null, (select id from public.skills where slug = 'read-g7-evidence-inference'), null, 'medium',
   $q$Which detail best supports the inference that beaver dams can help an area during a drought?$q$, $q$[{"text":"Ducks and herons feed along the edges of the ponds that beavers build.","is_correct":false,"misconception_token":"wrong-supporting-detail"},{"text":"Streams below beaver dams often keep flowing longer during dry summers.","is_correct":true},{"text":"In many areas, beavers were trapped or removed from their streams.","is_correct":false,"misconception_token":"wrong-supporting-detail"},{"text":"Beaver dams can flood roads and farm fields that people depend on.","is_correct":false,"misconception_token":"wrong-supporting-detail"}]$q$::jsonb, $q$Streams below beaver dams often keep flowing longer during dry summers.$q$, $q$A drought is a long dry period, and paragraph 3 says streams below dams keep flowing longer in dry summers. The flooding detail shows a problem dams cause, not a benefit in dry weather.$q$, 'draft', '0f15e3de-08ef-5e31-bf53-4231f29ae673')
