  ('ce9d3165-8039-5163-84ce-8a22e5e97992', null, (select id from public.skills where slug = 'read-g7-evidence-inference'), null, 'medium',
   $q$Based on the passage, what can the reader infer about a rider who stayed at the front for an entire race?$q$, $q$[{"text":"She would use less energy because no other riders would be in her way.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"She would probably tire sooner than riders who took turns or stayed sheltered.","is_correct":true},{"text":"She would have the most energy saved for the sprint at the finish line.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She would be breaking a rule that requires riders to change places.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$She would probably tire sooner than riders who took turns or stayed sheltered.$q$, $q$The text says the front position is "so tiring" that teammates take turns, so a rider who never left it would wear out faster. Being in front means facing the most air, not using less energy.$q$, 'draft', 'b282c102-d8f5-538b-9475-b9d1ae229035')
